import Image from "next/image";

/** Annotated product renders (generated by scripts/process-media.mjs). */
export const featureCards = {
  meet: {
    src: "/images/zivoo-feature-meet.webp",
    alt: "Meet Zivoo: a learning friend that talks, listens and helps children learn out loud, with phonics, spelling, maths and stories.",
    caption: "A learning friend that talks, listens and helps children learn out loud.",
  },
  hey: {
    src: "/images/zivoo-feature-hey-zivoo.webp",
    alt: "Just say Hey Zivoo: microphone on top, glowing talk button that lights up while Zivoo listens, and a speaker with a warm, friendly voice.",
    caption: "Say “Hey Zivoo” or press the glowing talk button. Zivoo listens and answers out loud.",
  },
  practice: {
    src: "/images/zivoo-feature-practice.webp",
    alt: "Practice, out loud: example prompts for phonics (sound out cat), spelling (spell frog), maths (four ducks, one flies away) and stories.",
    caption: "Phonics, spelling, maths and stories: a patient practice partner, not a test.",
  },
  privacy: {
    src: "/images/zivoo-feature-privacy.webp",
    alt: "Back of Zivoo showing a physical microphone switch: slide to mute, slide back to talk. Parents see learning insights, never recordings.",
    caption: "A physical mic switch on the back: slide to mute, slide back to talk.",
  },
  battery: {
    src: "/images/zivoo-feature-battery.webp",
    alt: "Zivoo battery: designed for up to 50 hours per charge, with USB-C charging and a rechargeable battery inside.",
    caption: "Up to 50 hours per charge, with USB-C charging.",
  },
  size: {
    src: "/images/zivoo-feature-size.webp",
    alt: "Zivoo size: 16 cm wide, 14 cm tall and 9.4 cm deep, small enough to hug and to sit on a desk, shelf or bedside table.",
    caption: "16 × 14 × 9.4 cm: small enough to hug, sized for a desk, shelf or bedside table.",
  },
} as const;

export type FeatureCardKey = keyof typeof featureCards;

export function FeatureCards({ keys, sizes = "(min-width: 1100px) 380px, (min-width: 700px) 50vw, 100vw" }: { keys: FeatureCardKey[]; sizes?: string }) {
  return (
    <ul className="feature-cards">
      {keys.map((k) => {
        const c = featureCards[k];
        return (
          <li key={k}>
            <figure>
              <div className="card-frame">
                <Image src={c.src} alt={c.alt} fill sizes={sizes} loading="lazy" />
              </div>
              <figcaption>{c.caption}</figcaption>
            </figure>
          </li>
        );
      })}
    </ul>
  );
}

export function FeatureCard({ k, sizes = "(min-width: 900px) 50vw, 100vw" }: { k: FeatureCardKey; sizes?: string }) {
  const c = featureCards[k];
  return (
    <figure className="photo">
      <div className="photo-frame" style={{ aspectRatio: "1 / 1" }}>
        <Image src={c.src} alt={c.alt} fill sizes={sizes} loading="lazy" className="photo-img" />
      </div>
    </figure>
  );
}
